/// Purpose-specific dirty state for one open workbook.
///
/// Prompt state is intentionally independent from the state that must be serialized. In
/// particular, assigning `Workbook.Saved = true` clears only `prompt_dirty`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct WorkbookDirtyDomains {
    pub prompt_dirty: bool,
    pub semantic_dirty: bool,
    pub serialization_dirty: bool,
    pub formula_cache_dirty: bool,
    pub package_graph_dirty: bool,
    pub external_refresh_dirty: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct RuntimeCalculationSnapshot {
    input_digest: [u8; 32],
    state: WorkbookCalculationState,
}

#[derive(Debug, Clone)]
struct RuntimeWorkbook {
    loaded: LoadedXlsxWorkbook,
    external_data_policy: ExternalDataPolicy,
    chart_support_part_sources: BTreeMap<ChartId, Vec<RuntimeChartSupportPartSource>>,
    read_only: bool,
    source_path: Option<PathBuf>,
    prompt_dirty: bool,
    semantic_dirty: bool,
    formula_cache_dirty: bool,
    package_graph_dirty: bool,
    external_refresh_dirty: bool,
    calculation_snapshot: Option<RuntimeCalculationSnapshot>,
}

#[derive(Debug)]
struct RuntimeWorkbookMutationSnapshot {
    target_handle_value: u64,
    original_target: RuntimeWorkbook,
    workbook_handles: BTreeSet<u64>,
    objects: BTreeMap<u64, RuntimeObjectKind>,
    stale_objects: BTreeSet<u64>,
    next_handle: u64,
    next_object_handle: u64,
    next_created_workbook_index: u64,
    active_workbook: Option<WorkbookHandle>,
    active_chart: Option<(WorkbookHandle, ChartId, Option<ChartObjectsParent>)>,
    selection: Option<RuntimeSelection>,
    selection_range: Option<RangeSet>,
    last_goto_selection: Option<RuntimeSelection>,
    last_goto_range: Option<(WorkbookHandle, RangeSet)>,
    find_state: Option<RuntimeFindState>,
    cut_copy_mode: Option<i32>,
    clipboard: Option<RuntimeClipboard>,
}

impl RuntimeWorkbook {
    fn saved_for_prompt(&self) -> bool {
        !self.prompt_dirty
    }

    fn set_saved_for_prompt(&mut self, saved: bool) {
        self.prompt_dirty = !saved;
    }

    fn mark_semantic_dirty(&mut self) {
        self.prompt_dirty = true;
        self.semantic_dirty = true;
    }
}

