    fn chart_object_entries_for_sheet(
        &self,
        workbook: WorkbookHandle,
        sheet_id: SheetId,
    ) -> OmResult<Vec<(ChartObjectId, String)>> {
        let state = &self.runtime_workbook(workbook)?.loaded.state;
        if !state
            .worksheets()
            .iter()
            .any(|worksheet| worksheet.id == sheet_id)
        {
            return Err(OmError::new(OmErrorCode::NotFound, "unknown worksheet"));
        }
        let chart_sheet_primary_chart_id = state
            .chart_sheets
            .get(&sheet_id)
            .map(|binding| binding.chart_id);
        let mut entries = state
            .drawings
            .values()
            .filter(|drawing| drawing.host_sheet_id == sheet_id)
            .flat_map(|drawing| drawing.objects.iter())
            .filter_map(|object| match object {
                DrawingObjectModel::ChartFrame(chart_object)
                    if Some(chart_object.chart_id) != chart_sheet_primary_chart_id =>
                {
                    Some((
                        chart_object.z_order.unwrap_or(u32::MAX),
                        chart_object.id,
                        chart_object.name.clone(),
                    ))
                }
                DrawingObjectModel::ChartFrame(_) => None,
                DrawingObjectModel::UnsupportedRaw { .. } => None,
            })
            .enumerate()
            .map(|(fallback_index, (z_order, chart_object_id, name))| {
                (z_order, fallback_index, chart_object_id, name)
            })
            .collect::<Vec<_>>();
        entries.sort_by_key(|(z_order, fallback_index, _, _)| (*z_order, *fallback_index));
        Ok(entries
            .into_iter()
            .map(|(_, _, chart_object_id, name)| (chart_object_id, name))
            .collect())
    }

    fn chart_object_entries_for_selection(
        &self,
        workbook: WorkbookHandle,
        sheet_id: SheetId,
        chart_object_ids: Option<&[ChartObjectId]>,
    ) -> OmResult<Vec<(ChartObjectId, String)>> {
        let entries = self.chart_object_entries_for_sheet(workbook, sheet_id)?;
        let Some(chart_object_ids) = chart_object_ids else {
            return Ok(entries);
        };

        let mut selected = Vec::with_capacity(chart_object_ids.len());
        for chart_object_id in chart_object_ids {
            let Some((_, name)) = entries
                .iter()
                .find(|(candidate_id, _)| candidate_id == chart_object_id)
            else {
                return Err(OmError::new(
                    OmErrorCode::NotFound,
                    "chart object not found",
                ));
            };
            selected.push((*chart_object_id, name.clone()));
        }
        Ok(selected)
    }

    fn shape_range_chart_object_entries(
        &self,
        workbook: WorkbookHandle,
        source: &ShapeRangeSource,
    ) -> OmResult<Vec<(ChartObjectId, String)>> {
        match source {
            ShapeRangeSource::ChartObjects {
                sheet_id,
                chart_object_ids,
                ..
            } => self.chart_object_entries_for_selection(
                workbook,
                *sheet_id,
                chart_object_ids.as_deref(),
            ),
            ShapeRangeSource::ChartObject {
                chart_object_id, ..
            } => {
                let chart_object = self.chart_object_model(workbook, *chart_object_id)?;
                Ok(vec![(chart_object.id, chart_object.name.clone())])
            }
        }
    }

    fn shape_range_delegate_handle(
        &mut self,
        workbook: WorkbookHandle,
        source: &ShapeRangeSource,
        member: &str,
    ) -> OmResult<ObjectHandle> {
        match source {
            ShapeRangeSource::ChartObject {
                chart_object_id,
                parent,
            } => {
                self.chart_object_model(workbook, *chart_object_id)?;
                Ok(self.register_chart_object_handle_with_parent_origin(
                    workbook,
                    *chart_object_id,
                    Some(*parent),
                ))
            }
            ShapeRangeSource::ChartObjects {
                sheet_id,
                parent,
                chart_object_ids,
            } => {
                let single_shape_member =
                    matches!(member, "Name" | "Chart" | "Index" | "ZOrder" | "OnAction");
                if single_shape_member {
                    let entries = self.chart_object_entries_for_selection(
                        workbook,
                        *sheet_id,
                        chart_object_ids.as_deref(),
                    )?;
                    let [(chart_object_id, _)] = entries.as_slice() else {
                        return Err(OmError::unsupported(format!(
                            "ShapeRange.{member} is only available for a single chart object"
                        )));
                    };
                    return Ok(self.register_chart_object_handle_with_parent_origin(
                        workbook,
                        *chart_object_id,
                        Some(*parent),
                    ));
                }
                match chart_object_ids {
                    Some(chart_object_ids) => Ok(self
                        .register_chart_objects_selection_handle_with_parent(
                            workbook,
                            *sheet_id,
                            *parent,
                            chart_object_ids.clone(),
                        )),
                    None => Ok(self
                        .register_chart_objects_handle_with_parent(workbook, *sheet_id, *parent)),
                }
            }
        }
    }

    fn chart_object_model(
        &self,
        workbook: WorkbookHandle,
        chart_object_id: ChartObjectId,
    ) -> OmResult<&ChartObjectModel> {
        self.runtime_workbook(workbook)?
            .loaded
            .state
            .drawings
            .values()
            .flat_map(|drawing| drawing.objects.iter())
            .find_map(|object| match object {
                DrawingObjectModel::ChartFrame(chart_object)
                    if chart_object.id == chart_object_id =>
                {
                    Some(chart_object)
                }
                _ => None,
            })
            .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "chart object not found"))
    }

    fn chart_model(&self, workbook: WorkbookHandle, chart_id: ChartId) -> OmResult<&ChartModel> {
        self.runtime_workbook(workbook)?
            .loaded
            .state
            .charts
            .get(&chart_id)
            .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "chart not found"))
    }

    fn validate_legend_entry_index(
        &self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        entry_index: usize,
    ) -> OmResult<()> {
        let chart = self.chart_model(workbook, chart_id)?;
        if !chart.legend.as_ref().is_some_and(|legend| legend.visible) {
            return Err(OmError::new(
                OmErrorCode::NotFound,
                "chart legend not found",
            ));
        }
        if entry_index >= chart.series.len() {
            return Err(OmError::new(
                OmErrorCode::NotFound,
                "legend entry not found",
            ));
        }
        Ok(())
    }

    fn pending_drawing_relationship_graph_for_drawing(
        &self,
        workbook: WorkbookHandle,
        sheet_id: SheetId,
        drawing: &DrawingModel,
    ) -> OmResult<Option<PendingDrawingRelationshipGraph>> {
        let runtime = self.runtime_workbook(workbook)?;
        if let Some(graph) = runtime
            .loaded
            .pending_drawing_relationship_graphs
            .get(&drawing.id)
        {
            return Ok(Some(graph.clone()));
        }
        let Some(source_drawing_part_uri) = drawing.raw_part_uri.as_deref() else {
            if drawing.objects.iter().any(|object| {
                matches!(
                    object,
                    DrawingObjectModel::UnsupportedRaw {
                        relationship_ids,
                        ..
                    } if !relationship_ids.is_empty()
                )
            }) {
                return Err(OmError::new(
                    OmErrorCode::InvalidState,
                    format!(
                        "drawing {} has relationship-backed objects without a source part",
                        drawing.id.0
                    ),
                ));
            }
            return Ok(None);
        };
        let Some(support_parts) = runtime.loaded.sheet_drawing_support_parts.get(&sheet_id) else {
            return Ok(None);
        };
        let Some(summary) = support_parts.drawing_summaries.get(source_drawing_part_uri) else {
            if drawing.objects.iter().any(|object| {
                matches!(
                    object,
                    DrawingObjectModel::UnsupportedRaw {
                        relationship_ids,
                        ..
                    } if !relationship_ids.is_empty()
                )
            }) {
                return Err(OmError::new(
                    OmErrorCode::InvalidState,
                    format!(
                        "drawing {} relationship summary is missing",
                        drawing.id.0
                    ),
                ));
            }
            return Ok(None);
        };
        if summary.opaque_relationships.is_empty() {
            if drawing.objects.iter().any(|object| {
                matches!(
                    object,
                    DrawingObjectModel::UnsupportedRaw {
                        relationship_ids,
                        ..
                    } if !relationship_ids.is_empty()
                )
            }) {
                return Err(OmError::new(
                    OmErrorCode::InvalidState,
                    format!(
                        "drawing {} has opaque relationship ids missing from its package inventory",
                        drawing.id.0
                    ),
                ));
            }
            return Ok(None);
        }
        let root_relationships_part_uri =
            worksheet_relationships_part_uri_for(source_drawing_part_uri);
        let root_relationships_part = runtime
            .loaded
            .package
            .part(&root_relationships_part_uri)
            .ok_or_else(|| {
                OmError::new(
                    OmErrorCode::InvalidState,
                    format!(
                        "drawing {} relationship part is missing: {}",
                        drawing.id.0, root_relationships_part_uri
                    ),
                )
            })?;
        let root_relationships_part_source_bytes = support_parts
            .drawing_relationships_part_source_bytes
            .get(&root_relationships_part_uri)
            .cloned()
            .unwrap_or_else(|| root_relationships_part.bytes.clone());
        let root_relationships = summary
            .opaque_relationships
            .iter()
            .map(|relationship| PendingPackageRelationship {
                relationship_id: relationship.relationship_id.clone(),
                relationship_type: relationship.relationship_type.clone(),
                target: relationship.target.clone(),
                target_mode: relationship.target_mode.clone(),
            })
            .collect::<Vec<_>>();
        for relationship in &root_relationships {
            validate_pending_runtime_relationship(relationship)?;
        }
        let expected_relationship_ids = drawing
            .objects
            .iter()
            .filter_map(|object| match object {
                DrawingObjectModel::UnsupportedRaw {
                    relationship_ids,
                    ..
                } => Some(relationship_ids),
                DrawingObjectModel::ChartFrame(_) => None,
            })
            .flatten()
            .map(String::as_str)
            .collect::<BTreeSet<_>>();
        let inventoried_relationship_ids = root_relationships
            .iter()
            .map(|relationship| relationship.relationship_id.as_str())
            .collect::<BTreeSet<_>>();
        if !expected_relationship_ids.is_subset(&inventoried_relationship_ids) {
            return Err(OmError::new(
                OmErrorCode::InvalidState,
                format!(
                    "drawing {} has opaque relationship ids missing from its package inventory",
                    drawing.id.0
                ),
            ));
        }

        let mut parts = BTreeMap::new();
        for relationship in &root_relationships {
            if !pending_package_relationship_is_external(relationship) {
                collect_pending_package_part_graph(
                    &runtime.loaded.package,
                    &relationship.target,
                    &mut parts,
                )?;
            }
        }
        Ok(Some(PendingDrawingRelationshipGraph {
            source_drawing_part_uri: source_drawing_part_uri.to_string(),
            root_relationships_part_source_bytes,
            root_relationships_part_compression: root_relationships_part.compression,
            root_relationships,
            parts,
        }))
    }

    fn pending_chart_relationship_graph_for_chart(
        &self,
        workbook: WorkbookHandle,
        sheet_id: SheetId,
        chart: &ChartModel,
    ) -> OmResult<Option<PendingChartRelationshipGraph>> {
        let runtime = self.runtime_workbook(workbook)?;
        if let Some(graph) = runtime
            .loaded
            .pending_chart_relationship_graphs
            .get(&chart.id)
        {
            return Ok(Some(graph.clone()));
        }
        let Some(source_chart_part_uri) = chart.raw_part_uri.as_deref() else {
            return Ok(None);
        };
        let Some(support_parts) = runtime.loaded.sheet_drawing_support_parts.get(&sheet_id) else {
            return Ok(None);
        };
        let Some(summary) = support_parts.chart_summaries.get(source_chart_part_uri) else {
            return Ok(None);
        };
        if summary.opaque_relationships.is_empty() {
            return Ok(None);
        }
        let source_chart_part = runtime
            .loaded
            .package
            .part(source_chart_part_uri)
            .ok_or_else(|| {
                OmError::new(
                    OmErrorCode::InvalidState,
                    format!("chart part is missing: {source_chart_part_uri}"),
                )
            })?;
        let root_relationships_part_uri =
            worksheet_relationships_part_uri_for(source_chart_part_uri);
        let root_relationships_part = runtime
            .loaded
            .package
            .part(&root_relationships_part_uri)
            .ok_or_else(|| {
                OmError::new(
                    OmErrorCode::InvalidState,
                    format!(
                        "chart relationship part is missing: {root_relationships_part_uri}"
                    ),
                )
            })?;
        let root_relationships_part_source_bytes = support_parts
            .chart_relationships_part_source_bytes
            .get(&root_relationships_part_uri)
            .cloned()
            .unwrap_or_else(|| root_relationships_part.bytes.clone());
        let root_relationships = summary
            .opaque_relationships
            .iter()
            .map(|relationship| PendingPackageRelationship {
                relationship_id: relationship.relationship_id.clone(),
                relationship_type: relationship.relationship_type.clone(),
                target: relationship.target.clone(),
                target_mode: relationship.target_mode.clone(),
            })
            .collect::<Vec<_>>();
        for relationship in &root_relationships {
            validate_pending_runtime_relationship(relationship)?;
        }
        let mut parts = BTreeMap::new();
        for relationship in &root_relationships {
            if !pending_package_relationship_is_external(relationship) {
                collect_pending_package_part_graph(
                    &runtime.loaded.package,
                    &relationship.target,
                    &mut parts,
                )?;
            }
        }
        Ok(Some(PendingChartRelationshipGraph {
            source_chart_part_uri: source_chart_part_uri.to_string(),
            source_chart_part_bytes: source_chart_part.bytes.clone(),
            source_chart_part_compression: source_chart_part.compression,
            root_relationships_part_source_bytes,
            root_relationships_part_compression: root_relationships_part.compression,
            root_relationships,
            parts,
        }))
    }

    fn chart_support_part_sources_for_chart(
        &self,
        workbook: WorkbookHandle,
        sheet_id: SheetId,
        chart: &ChartModel,
    ) -> OmResult<Vec<RuntimeChartSupportPartSource>> {
        let runtime = self.runtime_workbook(workbook)?;
        if let Some(sources) = runtime.chart_support_part_sources.get(&chart.id) {
            return Ok(sources.clone());
        }
        let Some(chart_part_uri) = chart.raw_part_uri.as_deref() else {
            return Ok(Vec::new());
        };
        let Some(summary) = runtime
            .loaded
            .sheet_drawing_support_parts
            .get(&sheet_id)
            .and_then(|support_parts| support_parts.chart_summaries.get(chart_part_uri))
        else {
            return Ok(Vec::new());
        };

        summary
            .support_relationships
            .iter()
            .map(|relationship| {
                let external = relationship
                    .target_mode
                    .as_deref()
                    .is_some_and(|target_mode| target_mode.eq_ignore_ascii_case("External"));
                let part = if external {
                    None
                } else {
                    let support_part = runtime
                        .loaded
                        .package
                        .part(&relationship.target)
                        .ok_or_else(|| {
                            OmError::new(
                                OmErrorCode::InvalidState,
                                format!("chart support part is missing: {}", relationship.target),
                            )
                        })?;
                    Some(RuntimeChartSupportPart {
                        bytes: support_part.bytes.clone(),
                        content_type: support_part.content_type.clone(),
                        compression: support_part.compression,
                    })
                };
                Ok(RuntimeChartSupportPartSource {
                    relationship_id: relationship.relationship_id.clone(),
                    relationship_type: relationship.relationship_type.clone(),
                    target: relationship.target.clone(),
                    target_mode: relationship.target_mode.clone(),
                    part,
                })
            })
            .collect()
    }

    fn chart_sheet_id_for_chart(
        &self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
    ) -> OmResult<Option<SheetId>> {
        self.chart_model(workbook, chart_id)?;
        Ok(self
            .runtime_workbook(workbook)?
            .loaded
            .state
            .chart_sheets
            .iter()
            .find_map(|(sheet_id, binding)| (binding.chart_id == chart_id).then_some(*sheet_id)))
    }

    fn embedded_chart_object_for_chart(
        &self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
    ) -> OmResult<Option<(SheetId, ChartObjectId, String)>> {
        if self.chart_sheet_id_for_chart(workbook, chart_id)?.is_some() {
            return Ok(None);
        }
        let state = &self.runtime_workbook(workbook)?.loaded.state;
        Ok(state.drawings.values().find_map(|drawing| {
            if !state
                .worksheets()
                .iter()
                .any(|worksheet| worksheet.id == drawing.host_sheet_id)
            {
                return None;
            }
            drawing.objects.iter().find_map(|object| match object {
                DrawingObjectModel::ChartFrame(chart_object)
                    if chart_object.chart_id == chart_id =>
                {
                    Some((
                        chart_object.host_sheet_id,
                        chart_object.id,
                        chart_object.name.clone(),
                    ))
                }
                DrawingObjectModel::ChartFrame(_) | DrawingObjectModel::UnsupportedRaw { .. } => {
                    None
                }
            })
        }))
    }

    fn delete_chart_object(
        &mut self,
        workbook: WorkbookHandle,
        chart_object_id: ChartObjectId,
    ) -> OmResult<bool> {
        let chart_object = self.chart_object_model(workbook, chart_object_id)?.clone();
        let chart = self.chart_model(workbook, chart_object.chart_id)?.clone();
        let raw_binding = chart_object.raw_binding.clone();
        let chart_will_be_removed = {
            let state = &self.runtime_workbook(workbook)?.loaded.state;
            !state
                .chart_sheets
                .values()
                .any(|binding| binding.chart_id == chart_object.chart_id)
                && !state.drawings.values().any(|drawing| {
                    drawing.objects.iter().any(|object| match object {
                        DrawingObjectModel::ChartFrame(candidate) => {
                            candidate.chart_id == chart_object.chart_id
                                && candidate.id != chart_object_id
                        }
                        DrawingObjectModel::UnsupportedRaw { .. } => false,
                    })
                })
        };
        let removed_chart_graph_part_uris = if chart_will_be_removed {
            if let Some(chart_part_uri) = chart.raw_part_uri.as_ref()
                && let Some(graph) = self.pending_chart_relationship_graph_for_chart(
                    workbook,
                    chart_object.host_sheet_id,
                    &chart,
                )?
            {
                exclusively_owned_package_graph_part_uris(
                    &self.runtime_workbook(workbook)?.loaded.package,
                    &BTreeSet::from([chart_part_uri.clone()]),
                    &[&graph.parts],
                )?
            } else {
                BTreeSet::new()
            }
        } else {
            BTreeSet::new()
        };

        let chart_was_removed = {
            let runtime = self.runtime_workbook_mut(workbook)?;
            if runtime.read_only {
                return Err(OmError::new(
                    OmErrorCode::InvalidState,
                    "cannot modify a read-only workbook",
                ));
            }
            let Some((drawing_id, object_index)) =
                runtime
                    .loaded
                    .state
                    .drawings
                    .iter()
                    .find_map(|(drawing_id, drawing)| {
                        drawing
                            .objects
                            .iter()
                            .position(|object| match object {
                                DrawingObjectModel::ChartFrame(candidate) => {
                                    candidate.id == chart_object_id
                                }
                                DrawingObjectModel::UnsupportedRaw { .. } => false,
                            })
                            .map(|object_index| (*drawing_id, object_index))
                    })
            else {
                return Err(OmError::new(
                    OmErrorCode::NotFound,
                    "chart object not found",
                ));
            };

            let drawing_raw_part_uri = runtime
                .loaded
                .state
                .drawings
                .get(&drawing_id)
                .and_then(|drawing| drawing.raw_part_uri.clone());
            let drawing_is_empty = {
                let drawing = runtime
                    .loaded
                    .state
                    .drawings
                    .get_mut(&drawing_id)
                    .expect("drawing id located above");
                drawing.objects.remove(object_index);
                drawing.dirty = true;
                drawing.objects.is_empty()
            };
            let mut removed_chart_part_uri = None;
            let mut removed_chart_support_part_uris = Vec::<String>::new();
            let mut chart_was_removed = false;
            let chart_still_referenced = runtime
                .loaded
                .state
                .chart_sheets
                .values()
                .any(|binding| binding.chart_id == chart_object.chart_id)
                || runtime.loaded.state.drawings.values().any(|drawing| {
                    drawing.objects.iter().any(|object| match object {
                        DrawingObjectModel::ChartFrame(candidate) => {
                            candidate.chart_id == chart_object.chart_id
                        }
                        DrawingObjectModel::UnsupportedRaw { .. } => false,
                    })
                });
            if !chart_still_referenced
                && let Some(removed_chart) =
                    runtime.loaded.state.charts.remove(&chart_object.chart_id)
            {
                chart_was_removed = true;
                removed_chart_part_uri = removed_chart.raw_part_uri;
                runtime
                    .loaded
                    .pending_chart_relationship_graphs
                    .remove(&chart_object.chart_id);
                runtime
                    .chart_support_part_sources
                    .remove(&chart_object.chart_id);
            }

            if drawing_is_empty {
                runtime.loaded.state.drawings.remove(&drawing_id);
                runtime
                    .loaded
                    .pending_drawing_relationship_graphs
                    .remove(&drawing_id);
            }

            if let Some(raw_binding) = raw_binding.as_deref()
                && let Some((drawing_part_uri, chart_relationship_id)) =
                    raw_binding.rsplit_once('#')
            {
                let drawing_relationship_ids = runtime
                    .loaded
                    .sheet_drawing_support_parts
                    .get(&chart_object.host_sheet_id)
                    .map(|support_parts| {
                        support_parts
                            .drawing_relationships
                            .iter()
                            .filter_map(|binding| {
                                (binding.target == drawing_part_uri)
                                    .then_some(binding.relationship_id.clone())
                            })
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default();
                if let Some(support_parts) = runtime
                    .loaded
                    .sheet_drawing_support_parts
                    .get_mut(&chart_object.host_sheet_id)
                {
                    if drawing_is_empty {
                        support_parts
                            .drawing_part_uris
                            .retain(|part_uri| part_uri != drawing_part_uri);
                        support_parts
                            .drawing_part_source_bytes
                            .remove(drawing_part_uri);
                        support_parts.drawing_summaries.remove(drawing_part_uri);
                        let drawing_rels_part_uri =
                            worksheet_relationships_part_uri_for(drawing_part_uri);
                        support_parts
                            .drawing_relationships_part_uris
                            .retain(|part_uri| part_uri != &drawing_rels_part_uri);
                        support_parts
                            .drawing_relationships_part_source_bytes
                            .remove(&drawing_rels_part_uri);
                        for relationship_id in &drawing_relationship_ids {
                            support_parts
                                .drawing_relationship_ids
                                .retain(|candidate| candidate != relationship_id);
                            support_parts
                                .drawing_relationships
                                .retain(|binding| &binding.relationship_id != relationship_id);
                        }
                    } else if let Some(summary) =
                        support_parts.drawing_summaries.get_mut(drawing_part_uri)
                    {
                        summary.anchors.retain(|anchor| {
                            !anchor
                                .chart_relationship_ids
                                .iter()
                                .any(|relationship_id| relationship_id == chart_relationship_id)
                        });
                        summary
                            .chart_relationship_ids
                            .retain(|relationship_id| relationship_id != chart_relationship_id);
                        summary
                            .chart_relationships
                            .retain(|binding| binding.relationship_id != chart_relationship_id);
                    }

                    if let Some(chart_part_uri) = removed_chart_part_uri.as_ref() {
                        if let Some(summary) = support_parts.chart_summaries.remove(chart_part_uri)
                        {
                            if let Some(chart_rels_part_uri) = summary.relationships_part_uri {
                                support_parts
                                    .chart_relationships_part_uris
                                    .retain(|part_uri| part_uri != &chart_rels_part_uri);
                                support_parts
                                    .chart_relationships_part_source_bytes
                                    .remove(&chart_rels_part_uri);
                            }
                            for relationship in summary.support_relationships {
                                removed_chart_support_part_uris.push(relationship.target);
                            }
                        }
                        support_parts
                            .chart_part_uris
                            .retain(|part_uri| part_uri != chart_part_uri);
                        support_parts.chart_part_source_bytes.remove(chart_part_uri);
                        for part_uri in &removed_chart_support_part_uris {
                            support_parts
                                .chart_support_part_uris
                                .retain(|candidate| candidate != part_uri);
                            support_parts
                                .chart_support_part_source_bytes
                                .remove(part_uri);
                        }
                        for part_uri in &removed_chart_graph_part_uris {
                            support_parts
                                .chart_opaque_relationship_part_uris
                                .retain(|candidate| candidate != part_uri);
                            support_parts
                                .chart_opaque_relationship_part_source_bytes
                                .remove(part_uri);
                        }
                    }
                }

                if drawing_is_empty {
                    if let Some(drawing_part_uri) = drawing_raw_part_uri.as_ref() {
                        runtime.loaded.package.remove_part(drawing_part_uri);
                        runtime.loaded.package.remove_part(
                            worksheet_relationships_part_uri_for(drawing_part_uri).as_str(),
                        );
                    }
                    if !drawing_relationship_ids.is_empty() {
                        let worksheet_part_uri = runtime
                            .loaded
                            .state
                            .worksheets()
                            .iter()
                            .find(|worksheet| worksheet.id == chart_object.host_sheet_id)
                            .and_then(|worksheet| worksheet.part_uri.clone())
                            .ok_or_else(|| {
                                OmError::new(
                                    OmErrorCode::InvalidState,
                                    "chart object host worksheet is missing a part uri",
                                )
                            })?;
                        if let Some(worksheet_xml) = runtime
                            .loaded
                            .package
                            .part(worksheet_part_uri.as_str())
                            .map(|part| part.bytes.clone())
                        {
                            let relationship_ids = drawing_relationship_ids
                                .iter()
                                .map(String::as_str)
                                .collect::<BTreeSet<_>>();
                            let mut reader =
                                Reader::from_reader(Cursor::new(worksheet_xml.as_slice()));
                            reader.config_mut().trim_text(false);
                            let mut writer = Writer::new(Cursor::new(Vec::new()));
                            let mut buffer = Vec::new();
                            let mut skip_depth = 0usize;
                            loop {
                                match reader.read_event_into(&mut buffer) {
                                    Ok(Event::Start(_)) if skip_depth > 0 => {
                                        skip_depth += 1;
                                    }
                                    Ok(Event::End(_)) if skip_depth > 0 => {
                                        skip_depth -= 1;
                                    }
                                    Ok(Event::Empty(element))
                                        if xml_local_name(element.name().as_ref())
                                            == b"drawing" =>
                                    {
                                        let mut should_strip = false;
                                        for attr in element.attributes() {
                                            let attr = attr.map_err(runtime_xml_error)?;
                                            if attr.key.as_ref() != b"r:id" {
                                                continue;
                                            }
                                            let value = attr
                                                .decode_and_unescape_value(reader.decoder())
                                                .map_err(runtime_xml_error)?
                                                .into_owned();
                                            if relationship_ids.contains(value.as_str()) {
                                                should_strip = true;
                                                break;
                                            }
                                        }
                                        if !should_strip {
                                            writer
                                                .write_event(Event::Empty(element.into_owned()))
                                                .map_err(runtime_xml_error)?;
                                        }
                                    }
                                    Ok(Event::Start(element))
                                        if xml_local_name(element.name().as_ref())
                                            == b"drawing" =>
                                    {
                                        let mut should_strip = false;
                                        for attr in element.attributes() {
                                            let attr = attr.map_err(runtime_xml_error)?;
                                            if attr.key.as_ref() != b"r:id" {
                                                continue;
                                            }
                                            let value = attr
                                                .decode_and_unescape_value(reader.decoder())
                                                .map_err(runtime_xml_error)?
                                                .into_owned();
                                            if relationship_ids.contains(value.as_str()) {
                                                should_strip = true;
                                                break;
                                            }
                                        }
                                        if should_strip {
                                            skip_depth = 1;
                                        } else {
                                            writer
                                                .write_event(Event::Start(element.into_owned()))
                                                .map_err(runtime_xml_error)?;
                                        }
                                    }
                                    Ok(Event::Eof) => break,
                                    Ok(event) if skip_depth == 0 => writer
                                        .write_event(event.into_owned())
                                        .map_err(runtime_xml_error)?,
                                    Ok(_) => {}
                                    Err(error) => return Err(runtime_xml_error(error)),
                                }
                                buffer.clear();
                            }
                            runtime.loaded.package.replace_part_bytes(
                                worksheet_part_uri.as_str(),
                                writer.into_inner().into_inner(),
                            )?;
                        }
                        let worksheet_rels_part_uri =
                            worksheet_relationships_part_uri_for(worksheet_part_uri.as_str());
                        if let Some(worksheet_rels_xml) = runtime
                            .loaded
                            .package
                            .part(worksheet_rels_part_uri.as_str())
                            .map(|part| part.bytes.clone())
                        {
                            let updated_worksheet_rels = strip_relationship_entries_by_id(
                                worksheet_rels_xml.as_slice(),
                                &drawing_relationship_ids,
                            )?;
                            runtime.loaded.package.replace_part_bytes(
                                worksheet_rels_part_uri.as_str(),
                                updated_worksheet_rels.clone(),
                            )?;
                            if let Some(worksheet_support_parts) = runtime
                                .loaded
                                .worksheet_support_parts
                                .get_mut(&chart_object.host_sheet_id)
                            {
                                worksheet_support_parts.relationships_part_source_bytes =
                                    Some(updated_worksheet_rels);
                            }
                        }
                        if let Some(worksheet_support_parts) = runtime
                            .loaded
                            .worksheet_support_parts
                            .get_mut(&chart_object.host_sheet_id)
                            && let Some(summary) =
                                worksheet_support_parts.relationships_summary.as_mut()
                        {
                            let removed_relationship_ids = drawing_relationship_ids
                                .iter()
                                .map(String::as_str)
                                .collect::<BTreeSet<_>>();
                            let removed_indexes = summary
                                .relationship_ids
                                .iter()
                                .enumerate()
                                .filter_map(|(index, relationship_id)| {
                                    removed_relationship_ids
                                        .contains(relationship_id.as_str())
                                        .then_some(index)
                                })
                                .collect::<BTreeSet<_>>();
                            summary.relationship_ids = summary
                                .relationship_ids
                                .iter()
                                .enumerate()
                                .filter_map(|(index, relationship_id)| {
                                    (!removed_indexes.contains(&index))
                                        .then_some(relationship_id.clone())
                                })
                                .collect();
                            summary.relationship_attr_maps = summary
                                .relationship_attr_maps
                                .iter()
                                .enumerate()
                                .filter_map(|(index, attr_map)| {
                                    (!removed_indexes.contains(&index)).then_some(attr_map.clone())
                                })
                                .collect();
                            summary.relationship_inner_xmls = summary
                                .relationship_inner_xmls
                                .iter()
                                .enumerate()
                                .filter_map(|(index, inner_xml)| {
                                    (!removed_indexes.contains(&index)).then_some(inner_xml.clone())
                                })
                                .collect();
                            let mut relationship_index = 0usize;
                            summary.root_child_names.retain(|child_name| {
                                if child_name != "Relationship" {
                                    return true;
                                }
                                let remove = removed_indexes.contains(&relationship_index);
                                relationship_index += 1;
                                !remove
                            });
                        }
                    }
                } else if let Some(drawing_xml) = runtime
                    .loaded
                    .package
                    .part(drawing_part_uri)
                    .map(|part| part.bytes.clone())
                {
                    let mut reader = Reader::from_reader(Cursor::new(drawing_xml.as_slice()));
                    reader.config_mut().trim_text(false);
                    let mut writer = Writer::new(Cursor::new(Vec::new()));
                    let mut buffer = Vec::new();
                    let mut anchor_depth = 0usize;
                    let mut anchor_contains_deleted_chart = false;
                    let mut pending_anchor_events = Vec::<Event<'static>>::new();
                    loop {
                        match reader.read_event_into(&mut buffer) {
                            Ok(Event::Start(element)) => {
                                let local_name = xml_local_name(element.name().as_ref()).to_vec();
                                let is_anchor = matches!(
                                    local_name.as_slice(),
                                    b"twoCellAnchor" | b"oneCellAnchor" | b"absoluteAnchor"
                                );
                                if anchor_depth == 0 && is_anchor {
                                    anchor_depth = 1;
                                    anchor_contains_deleted_chart = false;
                                    pending_anchor_events.push(Event::Start(element.into_owned()));
                                } else if anchor_depth > 0 {
                                    if local_name.as_slice() == b"chart" {
                                        for attr in element.attributes() {
                                            let attr = attr.map_err(runtime_xml_error)?;
                                            if attr.key.as_ref() != b"r:id" {
                                                continue;
                                            }
                                            let value = attr
                                                .decode_and_unescape_value(reader.decoder())
                                                .map_err(runtime_xml_error)?
                                                .into_owned();
                                            if value == chart_relationship_id {
                                                anchor_contains_deleted_chart = true;
                                                break;
                                            }
                                        }
                                    }
                                    anchor_depth += 1;
                                    pending_anchor_events.push(Event::Start(element.into_owned()));
                                } else {
                                    writer
                                        .write_event(Event::Start(element.into_owned()))
                                        .map_err(runtime_xml_error)?;
                                }
                            }
                            Ok(Event::Empty(element)) => {
                                let local_name = xml_local_name(element.name().as_ref()).to_vec();
                                if anchor_depth > 0 {
                                    if local_name.as_slice() == b"chart" {
                                        for attr in element.attributes() {
                                            let attr = attr.map_err(runtime_xml_error)?;
                                            if attr.key.as_ref() != b"r:id" {
                                                continue;
                                            }
                                            let value = attr
                                                .decode_and_unescape_value(reader.decoder())
                                                .map_err(runtime_xml_error)?
                                                .into_owned();
                                            if value == chart_relationship_id {
                                                anchor_contains_deleted_chart = true;
                                                break;
                                            }
                                        }
                                    }
                                    pending_anchor_events.push(Event::Empty(element.into_owned()));
                                } else {
                                    writer
                                        .write_event(Event::Empty(element.into_owned()))
                                        .map_err(runtime_xml_error)?;
                                }
                            }
                            Ok(Event::End(element)) => {
                                let local_name = xml_local_name(element.name().as_ref()).to_vec();
                                if anchor_depth > 0 {
                                    pending_anchor_events.push(Event::End(element.into_owned()));
                                    if matches!(
                                        local_name.as_slice(),
                                        b"twoCellAnchor" | b"oneCellAnchor" | b"absoluteAnchor"
                                    ) && anchor_depth == 1
                                    {
                                        if !anchor_contains_deleted_chart {
                                            for event in pending_anchor_events.drain(..) {
                                                writer
                                                    .write_event(event)
                                                    .map_err(runtime_xml_error)?;
                                            }
                                        } else {
                                            pending_anchor_events.clear();
                                        }
                                        anchor_depth = 0;
                                        anchor_contains_deleted_chart = false;
                                    } else {
                                        anchor_depth = anchor_depth.saturating_sub(1);
                                    }
                                } else {
                                    writer
                                        .write_event(Event::End(element.into_owned()))
                                        .map_err(runtime_xml_error)?;
                                }
                            }
                            Ok(Event::Eof) => break,
                            Ok(event) if anchor_depth > 0 => {
                                pending_anchor_events.push(event.into_owned());
                            }
                            Ok(event) => writer
                                .write_event(event.into_owned())
                                .map_err(runtime_xml_error)?,
                            Err(error) => return Err(runtime_xml_error(error)),
                        }
                        buffer.clear();
                    }
                    runtime
                        .loaded
                        .package
                        .replace_part_bytes(drawing_part_uri, writer.into_inner().into_inner())?;
                    let drawing_rels_part_uri =
                        worksheet_relationships_part_uri_for(drawing_part_uri);
                    if let Some(drawing_rels_xml) = runtime
                        .loaded
                        .package
                        .part(drawing_rels_part_uri.as_str())
                        .map(|part| part.bytes.clone())
                    {
                        runtime.loaded.package.replace_part_bytes(
                            drawing_rels_part_uri.as_str(),
                            strip_relationship_entries_by_id(
                                drawing_rels_xml.as_slice(),
                                &[chart_relationship_id.to_string()],
                            )?,
                        )?;
                    }
                }
            }

            let mut content_type_overrides_to_strip = Vec::<String>::new();
            if drawing_is_empty && let Some(drawing_part_uri) = drawing_raw_part_uri.as_ref() {
                content_type_overrides_to_strip.push(drawing_part_uri.clone());
            }
            if let Some(chart_part_uri) = removed_chart_part_uri {
                let chart_rels_part_uri =
                    worksheet_relationships_part_uri_for(chart_part_uri.as_str());
                runtime.loaded.package.remove_part(chart_part_uri.as_str());
                runtime
                    .loaded
                    .package
                    .remove_part(chart_rels_part_uri.as_str());
                content_type_overrides_to_strip.push(chart_part_uri);
            }
            for part_uri in removed_chart_support_part_uris {
                runtime.loaded.package.remove_part(part_uri.as_str());
                content_type_overrides_to_strip.push(part_uri);
            }
            for part_uri in removed_chart_graph_part_uris {
                runtime.loaded.package.remove_part(part_uri.as_str());
                runtime.loaded.package.remove_part(
                    worksheet_relationships_part_uri_for(part_uri.as_str()).as_str(),
                );
                content_type_overrides_to_strip.push(part_uri);
            }
            if !content_type_overrides_to_strip.is_empty()
                && let Some(content_types_xml) = runtime
                    .loaded
                    .package
                    .part(CONTENT_TYPES_PART_NAME)
                    .map(|part| part.bytes.clone())
            {
                runtime.loaded.package.replace_part_bytes(
                    CONTENT_TYPES_PART_NAME,
                    strip_content_type_overrides(
                        content_types_xml.as_slice(),
                        &content_type_overrides_to_strip,
                    )?,
                )?;
            }

            runtime.mark_semantic_dirty();
            chart_was_removed
        };

        self.stale_chart_object_handles_for_id(workbook, chart_object_id);
        if chart_was_removed {
            self.stale_chart_handles_for_chart(workbook, chart_object.chart_id);
            if self
                .active_chart
                .is_some_and(|(active_workbook, active_chart_id, _)| {
                    active_workbook == workbook && active_chart_id == chart_object.chart_id
                })
            {
                self.active_chart = None;
            }
        }
        self.find_state = None;
        self.cut_copy_mode = None;
        self.clipboard = None;

        Ok(true)
    }

    fn duplicate_chart_object(
        &mut self,
        workbook: WorkbookHandle,
        chart_object_id: ChartObjectId,
    ) -> OmResult<ChartObjectId> {
        let source_chart_object = self.chart_object_model(workbook, chart_object_id)?.clone();
        if matches!(
            source_chart_object.anchor.as_ref(),
            None | Some(DrawingAnchor::UnsupportedRaw)
        ) {
            return Err(OmError::unsupported(
                "ChartObject.Duplicate requires a supported drawing anchor",
            ));
        }
        let source_chart = self
            .chart_model(workbook, source_chart_object.chart_id)?
            .clone();
        let host_sheet_id = source_chart_object.host_sheet_id;
        let source_chart_support_part_sources = self.chart_support_part_sources_for_chart(
            workbook,
            host_sheet_id,
            &source_chart,
        )?;
        let source_pending_chart_relationship_graph = self
            .pending_chart_relationship_graph_for_chart(
                workbook,
                host_sheet_id,
                &source_chart,
            )?;

        let runtime = self.runtime_workbook_mut(workbook)?;
        if runtime.read_only {
            return Err(OmError::new(
                OmErrorCode::InvalidState,
                "cannot modify a read-only workbook",
            ));
        }
        if !runtime
            .loaded
            .state
            .worksheets()
            .iter()
            .any(|worksheet| worksheet.id == host_sheet_id)
        {
            return Err(OmError::new(
                OmErrorCode::NotFound,
                "chart object host worksheet was not found",
            ));
        }
        let Some(drawing_id) =
            runtime
                .loaded
                .state
                .drawings
                .iter()
                .find_map(|(drawing_id, drawing)| {
                    drawing
                        .objects
                        .iter()
                        .any(|object| match object {
                            DrawingObjectModel::ChartFrame(candidate) => {
                                candidate.id == chart_object_id
                            }
                            DrawingObjectModel::UnsupportedRaw { .. } => false,
                        })
                        .then_some(*drawing_id)
                })
        else {
            return Err(OmError::new(
                OmErrorCode::NotFound,
                "chart object not found",
            ));
        };

        let workbook_id = runtime.loaded.state.model().id;
        let new_chart_id = ChartId(
            runtime
                .loaded
                .state
                .charts
                .keys()
                .map(|chart_id| chart_id.0)
                .max()
                .unwrap_or_default()
                + 1,
        );
        let new_chart_object_id = ChartObjectId(
            runtime
                .loaded
                .state
                .drawings
                .values()
                .flat_map(|drawing| drawing.objects.iter())
                .filter_map(|object| match object {
                    DrawingObjectModel::ChartFrame(chart_object) => Some(chart_object.id.0),
                    DrawingObjectModel::UnsupportedRaw { id, .. } => Some(id.0),
                })
                .max()
                .unwrap_or_default()
                + 1,
        );
        let existing_chart_object_names = runtime
            .loaded
            .state
            .drawings
            .values()
            .filter(|drawing| drawing.host_sheet_id == host_sheet_id)
            .flat_map(|drawing| drawing.objects.iter())
            .filter_map(|object| match object {
                DrawingObjectModel::ChartFrame(chart_object) => Some(chart_object.name.as_str()),
                DrawingObjectModel::UnsupportedRaw { .. } => None,
            })
            .collect::<Vec<_>>();
        let mut chart_object_number = existing_chart_object_names.len() + 1;
        let chart_object_name = loop {
            let candidate = format!("Chart {chart_object_number}");
            if !existing_chart_object_names
                .iter()
                .any(|name| name.eq_ignore_ascii_case(&candidate))
            {
                break candidate;
            }
            chart_object_number += 1;
        };
        let z_order = runtime
            .loaded
            .state
            .drawings
            .get(&drawing_id)
            .expect("drawing id located above")
            .objects
            .iter()
            .enumerate()
            .filter_map(|(fallback_index, object)| match object {
                DrawingObjectModel::ChartFrame(chart_object) => chart_object
                    .z_order
                    .or_else(|| u32::try_from(fallback_index).ok()),
                DrawingObjectModel::UnsupportedRaw { .. } => u32::try_from(fallback_index).ok(),
            })
            .max()
            .map_or(Some(0), |existing_z_order| existing_z_order.checked_add(1));

        let mut duplicated_chart = source_chart;
        duplicated_chart.id = new_chart_id;
        duplicated_chart.workbook_id = workbook_id;
        duplicated_chart.raw_part_uri = None;
        duplicated_chart.content_dirty = true;
        duplicated_chart.dirty = true;
        runtime
            .loaded
            .state
            .charts
            .insert(new_chart_id, duplicated_chart);
        if !source_chart_support_part_sources.is_empty() {
            runtime
                .chart_support_part_sources
                .insert(new_chart_id, source_chart_support_part_sources);
        }
        if let Some(pending_chart_relationship_graph) =
            source_pending_chart_relationship_graph
        {
            runtime
                .loaded
                .pending_chart_relationship_graphs
                .insert(new_chart_id, pending_chart_relationship_graph);
        }

        let mut duplicated_chart_object = source_chart_object;
        duplicated_chart_object.id = new_chart_object_id;
        duplicated_chart_object.workbook_id = workbook_id;
        duplicated_chart_object.host_sheet_id = host_sheet_id;
        duplicated_chart_object.chart_id = new_chart_id;
        duplicated_chart_object.name = chart_object_name;
        duplicated_chart_object.non_visual_id = u32::try_from(new_chart_object_id.0).ok();
        duplicated_chart_object.raw_binding = None;
        duplicated_chart_object.z_order = z_order;
        duplicated_chart_object.dirty = true;

        let drawing = runtime
            .loaded
            .state
            .drawings
            .get_mut(&drawing_id)
            .expect("drawing id located above");
        drawing
            .objects
            .push(DrawingObjectModel::ChartFrame(duplicated_chart_object));
        drawing.dirty = true;
        runtime.mark_semantic_dirty();

        self.find_state = None;
        self.cut_copy_mode = None;
        self.clipboard = None;

        Ok(new_chart_object_id)
    }

    fn move_chart_objects_z_order(
        &mut self,
        workbook: WorkbookHandle,
        chart_object_ids: &[ChartObjectId],
        member: &str,
    ) -> OmResult<()> {
        let Some((first_chart_object_id, remaining_chart_object_ids)) =
            chart_object_ids.split_first()
        else {
            return Err(OmError::new(
                OmErrorCode::NotFound,
                "chart object not found",
            ));
        };
        let host_sheet_id = self
            .chart_object_model(workbook, *first_chart_object_id)?
            .host_sheet_id;
        for chart_object_id in remaining_chart_object_ids {
            let chart_object = self.chart_object_model(workbook, *chart_object_id)?;
            if chart_object.host_sheet_id != host_sheet_id {
                return Err(OmError::unsupported(
                    "ShapeRange.ZOrder is unavailable for mixed-sheet ranges",
                ));
            }
        }
        let mut ordered_chart_object_ids = self
            .chart_object_entries_for_sheet(workbook, host_sheet_id)?
            .into_iter()
            .map(|(chart_object_id, _)| chart_object_id)
            .collect::<Vec<_>>();
        if !chart_object_ids
            .iter()
            .all(|chart_object_id| ordered_chart_object_ids.contains(chart_object_id))
        {
            return Err(OmError::new(
                OmErrorCode::NotFound,
                "chart object not found",
            ));
        }
        if self.runtime_workbook(workbook)?.read_only {
            return Err(OmError::new(
                OmErrorCode::InvalidState,
                "cannot modify a read-only workbook",
            ));
        }
        if ordered_chart_object_ids.len() <= 1
            || ordered_chart_object_ids
                .iter()
                .all(|chart_object_id| chart_object_ids.contains(chart_object_id))
        {
            return Ok(());
        }
        match member {
            "BringToFront" => {
                let selected = ordered_chart_object_ids
                    .iter()
                    .copied()
                    .filter(|chart_object_id| chart_object_ids.contains(chart_object_id))
                    .collect::<Vec<_>>();
                ordered_chart_object_ids
                    .retain(|chart_object_id| !chart_object_ids.contains(chart_object_id));
                ordered_chart_object_ids.extend(selected);
            }
            "SendToBack" => {
                let mut reordered = ordered_chart_object_ids
                    .iter()
                    .copied()
                    .filter(|chart_object_id| chart_object_ids.contains(chart_object_id))
                    .collect::<Vec<_>>();
                reordered.extend(
                    ordered_chart_object_ids
                        .iter()
                        .copied()
                        .filter(|chart_object_id| !chart_object_ids.contains(chart_object_id)),
                );
                ordered_chart_object_ids = reordered;
            }
            "BringForward" => {
                if ordered_chart_object_ids.len() >= 2 {
                    for index in (0..ordered_chart_object_ids.len() - 1).rev() {
                        if chart_object_ids.contains(&ordered_chart_object_ids[index])
                            && !chart_object_ids.contains(&ordered_chart_object_ids[index + 1])
                        {
                            ordered_chart_object_ids.swap(index, index + 1);
                        }
                    }
                }
            }
            "SendBackward" => {
                for index in 1..ordered_chart_object_ids.len() {
                    if chart_object_ids.contains(&ordered_chart_object_ids[index])
                        && !chart_object_ids.contains(&ordered_chart_object_ids[index - 1])
                    {
                        ordered_chart_object_ids.swap(index, index - 1);
                    }
                }
            }
            _ => {
                return Err(OmError::unsupported(format!(
                    "ChartObject.{member} is not implemented as a z-order method"
                )));
            }
        }

        let runtime = self.runtime_workbook_mut(workbook)?;
        if runtime.read_only {
            return Err(OmError::new(
                OmErrorCode::InvalidState,
                "cannot modify a read-only workbook",
            ));
        }
        let mut workbook_dirty = false;
        for drawing in runtime.loaded.state.drawings.values_mut() {
            if drawing.host_sheet_id != host_sheet_id {
                continue;
            }
            let mut drawing_dirty = false;
            for object in &mut drawing.objects {
                let DrawingObjectModel::ChartFrame(chart_object) = object else {
                    continue;
                };
                let Some(new_position) = ordered_chart_object_ids
                    .iter()
                    .position(|candidate_id| *candidate_id == chart_object.id)
                else {
                    continue;
                };
                let new_z_order = u32::try_from(new_position).ok();
                if chart_object.z_order != new_z_order {
                    chart_object.z_order = new_z_order;
                    chart_object.dirty = true;
                    drawing_dirty = true;
                }
            }
            if drawing_dirty {
                drawing.dirty = true;
                workbook_dirty = true;
            }
        }
        if workbook_dirty {
            runtime.mark_semantic_dirty();
            self.find_state = None;
            self.cut_copy_mode = None;
            self.clipboard = None;
        }
        Ok(())
    }

    fn series_model(
        &self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        series_index: usize,
    ) -> OmResult<&SeriesModel> {
        self.chart_model(workbook, chart_id)?
            .series
            .get(series_index)
            .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "series not found"))
    }

    fn validate_point_index(
        &self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        series_index: usize,
        point_index: usize,
    ) -> OmResult<()> {
        let point_count =
            chart_series_point_count(self.series_model(workbook, chart_id, series_index)?);
        if point_index >= point_count {
            return Err(OmError::new(OmErrorCode::NotFound, "point not found"));
        }
        Ok(())
    }

    fn leader_lines_visible(
        &self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        series_index: usize,
    ) -> OmResult<bool> {
        let labels =
            chart_series_effective_data_labels(self.chart_model(workbook, chart_id)?, series_index);
        if labels.is_none() && self.series_model(workbook, chart_id, series_index).is_err() {
            return Err(OmError::new(OmErrorCode::NotFound, "series not found"));
        }
        Ok(labels
            .and_then(|labels| labels.has_leader_lines)
            .unwrap_or(false))
    }

    fn validate_data_label_index(
        &self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        series_index: usize,
        point_index: usize,
    ) -> OmResult<Option<&ChartDataLabelsModel>> {
        let chart = self.chart_model(workbook, chart_id)?;
        if chart.series.get(series_index).is_none() {
            return Err(OmError::new(OmErrorCode::NotFound, "series not found"));
        }
        let label_count = chart_data_labels_count_for_chart_series(chart, series_index);
        if point_index >= label_count {
            return Err(OmError::new(OmErrorCode::NotFound, "data label not found"));
        }
        Ok(chart_point_effective_data_labels(
            chart,
            series_index,
            point_index,
        ))
    }

    fn axis_model(
        &self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        axis_index: usize,
    ) -> OmResult<&AxisModel> {
        self.chart_model(workbook, chart_id)?
            .axes
            .get(axis_index)
            .filter(|axis| axis.deleted != Some(true))
            .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "axis not found"))
    }

    fn chart_group_model(
        &self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        group_index: usize,
    ) -> OmResult<&ChartModel> {
        let chart = self.chart_model(workbook, chart_id)?;
        if chart_group_axis_group(chart, group_index).is_ok() {
            Ok(chart)
        } else {
            Err(OmError::new(OmErrorCode::NotFound, "chart group not found"))
        }
    }

    fn chart_category_count_for_group(
        &self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        group_index: usize,
        full: bool,
    ) -> OmResult<usize> {
        let chart = self.chart_group_model(workbook, chart_id, group_index)?;
        let axis_group = chart_group_axis_group(chart, group_index)?;
        Ok(chart
            .series
            .iter()
            .find(|series| series.axis_group == axis_group)
            .map(|series| chart_series_category_count(series, full))
            .unwrap_or(0))
    }

    fn chart_category_name_for_index(
        &self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        group_index: usize,
        category_index: usize,
        full: bool,
    ) -> OmResult<String> {
        let state = &self.runtime_workbook(workbook)?.loaded.state;
        let chart = state
            .charts
            .get(&chart_id)
            .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "chart not found"))?;
        let axis_group = chart_group_axis_group(chart, group_index)?;
        let Some(series) = chart
            .series
            .iter()
            .find(|series| series.axis_group == axis_group)
        else {
            return Err(OmError::new(
                OmErrorCode::NotFound,
                "chart category not found",
            ));
        };
        let category_count = chart_series_category_count(series, full);
        if category_index >= category_count {
            return Err(OmError::new(
                OmErrorCode::NotFound,
                "chart category not found",
            ));
        }
        Ok(series
            .x_values
            .as_ref()
            .and_then(|source| {
                chart_source_category_value_text_for_index(state, source, category_index, full)
            })
            .unwrap_or_else(|| (category_index + 1).to_string()))
    }

    fn chart_category_is_filtered_for_index(
        &self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        group_index: usize,
        category_index: usize,
        full: bool,
    ) -> OmResult<bool> {
        if !full {
            return Ok(false);
        }
        let chart = self.chart_group_model(workbook, chart_id, group_index)?;
        let axis_group = chart_group_axis_group(chart, group_index)?;
        let Some(source) = chart
            .series
            .iter()
            .find(|series| series.axis_group == axis_group)
            .and_then(|series| series.x_values.as_ref())
        else {
            return Ok(false);
        };
        Ok(chart_source_full_category_is_filtered(source, category_index))
    }

    fn chart_group_radar_axis_index(
        &self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        group_index: usize,
    ) -> OmResult<usize> {
        let chart = self.chart_group_model(workbook, chart_id, group_index)?;
        if !chart_type_supports_radar_axis_labels(&chart.chart_type) {
            return Err(OmError::unsupported(
                "ChartGroup.RadarAxisLabels is only supported for radar chart groups",
            ));
        }
        let axis_group = chart_group_axis_group(chart, group_index)?;
        chart
            .axes
            .iter()
            .position(|axis| {
                axis.deleted != Some(true)
                    && axis.axis_group == axis_group
                    && matches!(axis.kind, ChartAxisKind::Category | ChartAxisKind::Date)
            })
            .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "radar axis labels not found"))
    }

    fn apply_chart_data_labels(
        &mut self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        data_labels: ChartDataLabelsModel,
    ) -> OmResult<()> {
        let runtime = self.runtime_workbook_mut(workbook)?;
        if runtime.read_only {
            return Err(OmError::new(
                OmErrorCode::InvalidState,
                "cannot modify a read-only workbook",
            ));
        }
        let chart = runtime
            .loaded
            .state
            .charts
            .get_mut(&chart_id)
            .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "chart not found"))?;
        let mut changed = false;
        if chart.data_labels.as_ref() != Some(&data_labels) {
            chart.data_labels = Some(data_labels.clone());
            changed = true;
        }
        for group in &mut chart.groups {
            if group.data_labels.as_ref() != Some(&data_labels) {
                group.data_labels = Some(data_labels.clone());
                group.dirty = true;
                changed = true;
            }
        }
        for series in &mut chart.series {
            if series.data_labels.is_some() {
                series.data_labels = None;
                changed = true;
            }
            if !series.point_data_labels.is_empty() {
                series.point_data_labels.clear();
                changed = true;
            }
        }
        if changed {
            chart.content_dirty = true;
            chart.dirty = true;
            runtime.mark_semantic_dirty();
            self.find_state = None;
            self.cut_copy_mode = None;
            self.clipboard = None;
        }
        Ok(())
    }

    fn chart_axis_index_for_type(
        &self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        axis_type: i32,
        axis_group: ChartAxisGroup,
    ) -> OmResult<Option<usize>> {
        Ok(self
            .chart_model(workbook, chart_id)?
            .axes
            .iter()
            .position(|axis| axis.deleted != Some(true) && match axis_type {
                XL_CATEGORY => {
                    axis.axis_group == axis_group
                        && matches!(axis.kind, ChartAxisKind::Category | ChartAxisKind::Date)
                }
                XL_VALUE => axis.axis_group == axis_group && axis.kind == ChartAxisKind::Value,
                XL_SERIES_AXIS => {
                    axis.axis_group == axis_group && axis.kind == ChartAxisKind::Series
                }
                _ => false,
            }))
    }

    fn set_chart_axis_presence(
        &mut self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        axis_type: i32,
        axis_group: ChartAxisGroup,
        has_axis: bool,
    ) -> OmResult<bool> {
        if !matches!(axis_type, XL_CATEGORY | XL_VALUE | XL_SERIES_AXIS) {
            return Err(OmError::invalid_argument(
                "Chart axis visibility supports category, value, and series axes",
            ));
        }

        let candidate = {
            let runtime = self.runtime_workbook(workbook)?;
            if runtime.read_only {
                return Err(OmError::new(
                    OmErrorCode::InvalidState,
                    "cannot modify a read-only workbook",
                ));
            }
            let mut chart = runtime
                .loaded
                .state
                .charts
                .get(&chart_id)
                .cloned()
                .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "chart not found"))?;
            if !chart_type_has_axes(&chart.chart_type) && has_axis {
                return Err(OmError::unsupported(
                    "axis visibility is unavailable for chart types without axes",
                ));
            }
            let axis_matches = |axis: &AxisModel| match axis_type {
                XL_CATEGORY => {
                    axis.axis_group == axis_group
                        && matches!(axis.kind, ChartAxisKind::Category | ChartAxisKind::Date)
                }
                XL_VALUE => axis.axis_group == axis_group && axis.kind == ChartAxisKind::Value,
                XL_SERIES_AXIS => {
                    axis.axis_group == axis_group && axis.kind == ChartAxisKind::Series
                }
                _ => false,
            };
            let axis_indices = chart
                .axes
                .iter()
                .enumerate()
                .filter_map(|(axis_index, axis)| axis_matches(axis).then_some(axis_index))
                .collect::<Vec<_>>();
            let mut topology_changed = false;
            let changed = if has_axis {
                if axis_indices
                    .iter()
                    .any(|axis_index| chart.axes[*axis_index].deleted != Some(true))
                {
                    false
                } else if !axis_indices.is_empty() {
                    for axis_index in axis_indices {
                        chart.axes[axis_index].deleted = Some(false);
                    }
                    true
                } else {
                    let (kind, preferred_axis_id) = match (axis_type, axis_group) {
                        (XL_CATEGORY, ChartAxisGroup::Primary) => (ChartAxisKind::Category, 10),
                        (XL_VALUE, ChartAxisGroup::Primary) => (ChartAxisKind::Value, 20),
                        (XL_SERIES_AXIS, ChartAxisGroup::Primary) => (ChartAxisKind::Series, 30),
                        (XL_CATEGORY, ChartAxisGroup::Secondary) => {
                            (ChartAxisKind::Category, 40)
                        }
                        (XL_VALUE, ChartAxisGroup::Secondary) => (ChartAxisKind::Value, 50),
                        (XL_SERIES_AXIS, ChartAxisGroup::Secondary) => {
                            (ChartAxisKind::Series, 60)
                        }
                        _ => unreachable!("axis type validated above"),
                    };
                    topology_changed =
                        ensure_chart_axis(&mut chart, kind, axis_group, preferred_axis_id);
                    topology_changed
                }
            } else {
                let mut hidden = false;
                for axis_index in axis_indices {
                    if chart.axes[axis_index].deleted != Some(true) {
                        chart.axes[axis_index].deleted = Some(true);
                        hidden = true;
                    }
                }
                hidden
            };
            if topology_changed {
                reconcile_chart_axis_crossings(&mut chart.axes);
            }
            if changed {
                chart.content_dirty = true;
                chart.dirty = true;
                preflight_chart_model_xml(runtime, &chart)?;
            }
            (changed, chart)
        };
        let (changed, candidate) = candidate;
        if changed {
            let runtime = self.runtime_workbook_mut(workbook)?;
            let chart = runtime
                .loaded
                .state
                .charts
                .get_mut(&chart_id)
                .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "chart not found"))?;
            *chart = candidate;
            runtime.mark_semantic_dirty();
            self.stale_axis_handles_for_chart(workbook, chart_id);
            self.find_state = None;
            self.cut_copy_mode = None;
            self.clipboard = None;
        }
        Ok(changed)
    }

