fn chart_data_labels_visible(data_labels: Option<&ChartDataLabelsModel>) -> bool {
    data_labels.is_some_and(|data_labels| {
        data_labels.show_legend_key.unwrap_or(false)
            || data_labels.show_series_name.unwrap_or(false)
            || data_labels.show_category_name.unwrap_or(false)
            || data_labels.show_value.unwrap_or(false)
            || data_labels.show_percentage.unwrap_or(false)
            || data_labels.show_bubble_size.unwrap_or(false)
    })
}

fn chart_series_effective_data_labels(
    chart: &ChartModel,
    series_index: usize,
) -> Option<&ChartDataLabelsModel> {
    chart
        .series
        .get(series_index)
        .and_then(|series| series.data_labels.as_ref())
        .or(chart.data_labels.as_ref())
}

fn chart_point_effective_data_labels(
    chart: &ChartModel,
    series_index: usize,
    point_index: usize,
) -> Option<&ChartDataLabelsModel> {
    chart
        .series
        .get(series_index)
        .and_then(|series| {
            u32::try_from(point_index)
                .ok()
                .and_then(|index| series.point_data_labels.get(&index))
                .or(series.data_labels.as_ref())
        })
        .or(chart.data_labels.as_ref())
}

fn chart_data_labels_count_for_chart_series(chart: &ChartModel, series_index: usize) -> usize {
    let Some(series) = chart.series.get(series_index) else {
        return 0;
    };
    if chart_data_labels_visible(chart_series_effective_data_labels(chart, series_index))
        || series
            .point_data_labels
            .values()
            .any(|data_labels| chart_data_labels_visible(Some(data_labels)))
    {
        chart_series_point_count(series).max(1)
    } else {
        0
    }
}

fn chart_series_point_count(series: &SeriesModel) -> usize {
    series
        .values
        .as_ref()
        .map(chart_source_point_count)
        .unwrap_or(0)
}

fn chart_series_category_count(series: &SeriesModel, full: bool) -> usize {
    series.x_values.as_ref().map_or_else(
        || chart_series_point_count(series),
        |source| {
            if full {
                source
                    .full_reference
                    .as_ref()
                    .map(|reference| chart_reference_target_point_count(reference.resolved.as_ref()))
                    .unwrap_or_else(|| chart_source_point_count(source))
            } else {
                chart_source_point_count(source)
            }
        },
    )
}

fn chart_source_point_count(source: &ChartSourceExpr) -> usize {
    chart_reference_target_point_count(source.resolved.as_ref())
}

fn chart_reference_target_point_count(target: Option<&ReferenceTarget>) -> usize {
    match target {
        Some(ReferenceTarget::Range(range)) => range
            .areas()
            .iter()
            .fold(0usize, |total, area| {
                total.saturating_add(chart_range_area_point_count(area))
            }),
        Some(ReferenceTarget::Array(array)) => array.rows.saturating_mul(array.cols),
        Some(ReferenceTarget::Value(_)) => 1,
        Some(_) | None => 1,
    }
}

fn chart_source_value_text_for_index(
    state: &WorkbookState,
    source: &ChartSourceExpr,
    index: usize,
) -> Option<String> {
    chart_reference_target_value_text_for_index(state, source.resolved.as_ref(), index)
}

fn chart_source_category_value_text_for_index(
    state: &WorkbookState,
    source: &ChartSourceExpr,
    index: usize,
    full: bool,
) -> Option<String> {
    let target = if full {
        source
            .full_reference
            .as_ref()
            .and_then(|reference| reference.resolved.as_ref())
            .or(source.resolved.as_ref())
    } else {
        source.resolved.as_ref()
    };
    chart_reference_target_value_text_for_index(state, target, index)
}

fn chart_reference_target_value_text_for_index(
    state: &WorkbookState,
    target: Option<&ReferenceTarget>,
    mut index: usize,
) -> Option<String> {
    match target {
        Some(ReferenceTarget::Range(range)) => {
            for area in range.areas() {
                let cell_count = chart_range_area_point_count(area);
                if index >= cell_count {
                    index -= cell_count;
                    continue;
                }
                let SheetScope::Single(sheet_id) = area.scope else {
                    return None;
                };
                let row_offset = index / area.rect.width() as usize;
                let col_offset = index % area.rect.width() as usize;
                let row = area.rect.row_first + row_offset as u32;
                let col = area.rect.col_first + col_offset as u32;
                return Some(
                    state
                        .cell(sheet_id, row, col)
                        .map(|cell| find_cell_value_text(&cell.value))
                        .unwrap_or_default(),
                );
            }
            None
        }
        Some(ReferenceTarget::Array(array)) => array.values.get(index).and_then(om_value_text),
        Some(ReferenceTarget::Value(value)) if index == 0 => Some(find_cell_value_text(value)),
        _ => None,
    }
}

fn chart_source_full_category_is_filtered(source: &ChartSourceExpr, index: usize) -> bool {
    let Some(full_reference) = source.full_reference.as_ref() else {
        return false;
    };
    let Some(cell) = chart_reference_target_cell_for_index(full_reference.resolved.as_ref(), index)
    else {
        return false;
    };
    !chart_reference_target_contains_cell(source.resolved.as_ref(), cell)
}

fn chart_reference_target_cell_for_index(
    target: Option<&ReferenceTarget>,
    mut index: usize,
) -> Option<(SheetId, u32, u32)> {
    let Some(ReferenceTarget::Range(range)) = target else {
        return None;
    };
    for area in range.areas() {
        let cell_count = chart_range_area_point_count(area);
        if index >= cell_count {
            index -= cell_count;
            continue;
        }
        let SheetScope::Single(sheet_id) = area.scope else {
            return None;
        };
        let row_offset = index / area.rect.width() as usize;
        let col_offset = index % area.rect.width() as usize;
        return Some((
            sheet_id,
            area.rect.row_first + row_offset as u32,
            area.rect.col_first + col_offset as u32,
        ));
    }
    None
}

fn chart_range_area_point_count(area: &RangeArea) -> usize {
    area.checked_cell_count_usize().unwrap_or(usize::MAX)
}

fn chart_reference_target_contains_cell(
    target: Option<&ReferenceTarget>,
    (sheet_id, row, col): (SheetId, u32, u32),
) -> bool {
    let Some(ReferenceTarget::Range(range)) = target else {
        return false;
    };
    range.areas().iter().any(|area| {
        area.scope == SheetScope::Single(sheet_id)
            && area.rect.row_first <= row
            && row <= area.rect.row_last
            && area.rect.col_first <= col
            && col <= area.rect.col_last
    })
}

fn om_value_text(value: &OmValue) -> Option<String> {
    match value {
        OmValue::Missing | OmValue::Empty | OmValue::Null => Some(String::new()),
        OmValue::Bool(true) => Some("TRUE".to_string()),
        OmValue::Bool(false) => Some("FALSE".to_string()),
        OmValue::Number(number) => Some(format_find_number(*number)),
        OmValue::Text(text) => Some(text.clone()),
        OmValue::Error(error) => Some(formula_cell_error_text(*error).to_string()),
        OmValue::Object(_) | OmValue::Array(_) => None,
    }
}

fn chart_number_xml_value(value: f64) -> String {
    if value.fract() == 0.0 {
        format!("{value:.0}")
    } else {
        value.to_string()
    }
}

fn preflight_chart_model_xml(runtime: &RuntimeWorkbook, chart: &ChartModel) -> OmResult<()> {
    let source_xml = if let Some(chart_part_uri) = chart.raw_part_uri.as_deref() {
        Some(
            runtime
                .loaded
                .package
                .part(chart_part_uri)
                .ok_or_else(|| {
                    OmError::new(
                        OmErrorCode::InvalidState,
                        format!("dirty chart part is missing: {chart_part_uri}"),
                    )
                })?
                .bytes
                .as_slice(),
        )
    } else {
        None
    };
    encode_chart_model_xml(source_xml, chart)?;
    Ok(())
}

